      def initialize(client)
        @client = client
      end

      # Totals.
      #
      # Event counts by status over the last N hours (live traffic only). Requires a full-access key. Counts
      # events (not unique emails), ordered by status name; test-mode traffic excluded.
      #
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [Integer] :hours 1-720. Limits: 422 invalid_parameter otherwise. Default: 24.
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::Stats]
      def get(params = {}, request_options: {}, **kwargs)
        @client.request(
          method: :get,
          path: "/stats",
          query: Util.params(params, kwargs),
          model: Models::Stats,
          request_options: request_options
        )
      end

      # Time series.
      #
      # Event counts by status in time buckets. Requires a full-access key. One point per (bucket, status);
      # empty buckets are not emitted. Test-mode traffic excluded.
      #
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [Integer] :hours 1-720 (422 invalid_parameter otherwise). Bucket size: <=1h → 60 s,
      #   <=6h → 300 s, <=24h → 1800 s, <=168h → 10800 s, otherwise 43200 s. Default: 24.
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::StatsTimeseries]
      def timeseries(params = {}, request_options: {}, **kwargs)
        @client.request(
          method: :get,
          path: "/stats/timeseries",
          query: Util.params(params, kwargs),
          model: Models::StatsTimeseries,
          request_options: request_options
        )
      end

      # Breakdown.
      #
      # Per-provider delivery, bounce classes, engagement and top clicked links. Requires a full-access key.
      # Providers are Gmail, Microsoft, Yahoo, Apple and Other. delayed counts emails that were delayed at
      # least once.
      #
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [Integer] :hours 1-720. Limits: 422 invalid_parameter otherwise. Default: 24.
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::StatsBreakdown]
      def breakdown(params = {}, request_options: {}, **kwargs)
        @client.request(
          method: :get,
          path: "/stats/breakdown",
          query: Util.params(params, kwargs),
          model: Models::StatsBreakdown,
          request_options: request_options
        )
      end

      # Metrics by domain, stream, tag or provider.
      #
      # Delivery and engagement of live mail by sending domain, stream, tag or mailbox provider, with rates
      # and a time series. Requires a full-access key. Counts are recipients, except delayed, opened and
      # clicked: unique emails. Delivery and bounce rates are of sent; complaint, open and click rates of
      # delivered. Test-mode mail is excluded. Kept for 400 days. An out-of-band bounce (a later bounce email
      # from the remote server) has no sending domain: it is grouped under an empty value. Totals and the
      # series count each email once whatever the dimension; with dimension=tag an email with several tags
      # appears in each of its tags' groups.
      #
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [String] :from RFC 3339 start. At most 400 days before to. Default: 7 days ago.
      # @option params [String] :to RFC 3339 end (exclusive). Default: now.
      # @option params [String] :granularity hour (ranges up to 31 days) or day for series. Default: hour up
      #   to 48 hours, else day.
      # @option params [String] :dimension domain, stream, tag or provider: adds groups, one row per value,
      #   busiest first.
      # @option params [String] :domain Only this sending (From) domain.
      # @option params [String] :stream transactional or broadcast.
      # @option params [String] :provider Gmail, Microsoft, Yahoo, Apple or Other.
      # @option params [String] :tag Only emails with this tag, as name=value. Cannot be combined with domain,
      #   stream or provider, and groups only by tag.
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::Metrics]
      def metrics(params = {}, request_options: {}, **kwargs)
        @client.request(
          method: :get,
          path: "/metrics",
          query: Util.params(params, kwargs),
          model: Models::Metrics,
          request_options: request_options
        )
      end
    end

    # zap.domains
    class Domains
      # @api private
      def initialize(client)
