      # get 403 test_key_restricted.
      #
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [String] :name Domain name (lowercased, trailing dot removed). Limits: valid hostname
      #   <=253 chars, else 422 invalid_parameter "invalid domain name" Required.
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::Domain]
      def create(params = {}, request_options: {}, **kwargs)
