      # Retrieve a domain.
      #
      # Retrieve a sending domain. Requires a full-access key.
      #
      # @param id [String] Domain id
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::Domain]
      def get(id, request_options: {})
        @client.request(
          method: :get,
          path: "/domains/#{Util.seg("id", id)}",
          model: Models::Domain,
          request_options: request_options
        )
      end

      # Update a domain.
      #
      # Set the domain's tracking defaults (opens, clicks, replies) and its outbound TLS policy. Requires a
      # full-access live key; test keys get 403 test_key_restricted. Fields left out keep their value. The
      # response is the domain, as in GET /domains/{id}. Reply tracking: each tracked email gets its own
      # signed Reply-To, e.g. r1-<email id>.<signature>@reply.acme.com, so replies come back tied to the exact
      # email. Each reply fires email.replied (classified as a person, out-of-office, unsubscribe request,
      # bounce…) and arrives as a received email; only replies a person wrote are forwarded. The display name
      # is kept (the Reply-To’s name, else the From name). One reply address takes at most 100 replies a day.
      #
      # @param id [String] Domain id
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [Boolean] :open_tracking Default open tracking for emails from this domain.
      # @option params [Boolean] :click_tracking Default click tracking for emails from this domain.
      # @option params [String] :tls Outbound encryption: opportunistic (default: encrypt whenever offered),
      #   required (TLS or no delivery) or verified (TLS with a valid certificate). Limits: other values → 422
      #   invalid_parameter "tls must be opportunistic, required or verified"
      # @option params [Boolean] :reply_tracking Default reply tracking for emails from this domain (override
      #   per email with tracking.replies). Limits: true without a reply_domain → 422 invalid_parameter
      #   "reply_tracking needs a reply_domain: add an inbound domain such as reply.<domain> first"
      # @option params [String] :reply_domain Where tracked reply addresses live: one of your inbound domains,
      #   MX-verified, equal to this domain or a subdomain of it (e.g. reply.acme.com). "" clears it. Limits:
      #   otherwise 422 invalid_parameter
      # @option params [String] :reply_forward_to Where replies a person wrote are forwarded: a plain address
      #   on one of your verified domains, or a confirmed forward destination; never a receiving address. ""
      #   (default) forwards to the email’s first Reply-To, else its From. Limits: otherwise 422
      #   invalid_parameter
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::Domain]
      def update(id, params = {}, request_options: {}, **kwargs)
        @client.request(
          method: :patch,
          path: "/domains/#{Util.seg("id", id)}",
          body: Util.params(params, kwargs),
          model: Models::Domain,
          request_options: request_options
        )
      end

      # Verify a domain.
      #
      # Check DKIM/SPF/DMARC DNS now and update the domain's status. Requires a full-access live key; test
      # keys get 403 test_key_restricted. found shows, per DNS name, what is published right now. For the root
      # domain only SPF-type TXT values are listed; a DMARC policy inherited from the parent domain is marked
      # “(inherited from _dmarc.<domain>)”.
      #
      # @param id [String] Domain id
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::Domain]
      def verify(id, request_options: {})
        @client.request(
          method: :post,
          path: "/domains/#{Util.seg("id", id)}/verify",
          model: Models::Domain,
          request_options: request_options
        )
      end

      # Delete a domain.
      #
      # Delete a sending domain. Requires a full-access live key; test keys get 403 test_key_restricted.
      #
      # @param id [String] Domain id
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [nil]
      def delete(id, request_options: {})
        @client.request(
          method: :delete,
          path: "/domains/#{Util.seg("id", id)}",
          model: nil,
          request_options: request_options
        )
      end

      # DMARC reports.
      #
      # DMARC aggregate reports about the domain: the address to publish in your DMARC record and what mailbox
      # providers reported. Requires a full-access key. Add rua to your DMARC record (keep your policy).
      # Providers send one report a day; reports are kept 400 days. ours marks ZapSMTP sending IPs: another IP
      # that fails DMARC is a service you have not set up (add its DKIM/SPF) or someone spoofing your domain.
      #
      # @param id [String] Domain id.
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [Integer] :days 1-180. Limits: 422 invalid_parameter otherwise. Default: 30.
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::DmarcSummary]
      def get_dmarc(id, params = {}, request_options: {}, **kwargs)
        @client.request(
          method: :get,
          path: "/domains/#{Util.seg("id", id)}/dmarc",
          query: Util.params(params, kwargs),
          model: Models::DmarcSummary,
          request_options: request_options
        )
      end

      # Domain reputation.
      #
      # Blocklist (DNSBL) status of a sending domain. Requires a full-access key. Customer domains are checked
      # automatically every 6 hours (operator-configurable). The exact JSON for codes/labels when empty (null
      # vs []) depends on the stored arrays; not verified.
      #
      # @param id [String] Domain id
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::DomainReputation]
      def get_reputation(id, request_options: {})
        @client.request(
          method: :get,
          path: "/domains/#{Util.seg("id", id)}/reputation",
          model: Models::DomainReputation,
          request_options: request_options
        )
      end

      # Check reputation now.
      #
      # Run a blocklist check of the domain now and return its reputation. Requires a full-access live key;
      # test keys get 403 test_key_restricted. At most once per minute per domain name. No Retry-After header
      # is set.
      #
      # @param id [String] Domain id
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::DomainReputation]
      def check_reputation(id, request_options: {})
        @client.request(
          method: :post,
          path: "/domains/#{Util.seg("id", id)}/reputation/check",
          model: Models::DomainReputation,
          request_options: request_options
        )
      end

      # Retrieve brand settings.
      #
      # Brand-in-the-inbox status: sender name, BIMI logo/certificate, DMARC enforcement and per-provider
      # readiness. Requires a full-access key.
      #
      # @param id [String] Domain id
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Models::Brand]
      def get_brand(id, request_options: {})
        @client.request(
