          model: Models::Brand,
          request_options: request_options
        )
      end

      # Update brand settings.
      #
      # Set the default sender name and upload/remove the BIMI logo and certificate. Requires a full-access
      # live key; test keys get 403 test_key_restricted. Hosted files are served publicly at
      # /bimi/<domain>/logo.svg and /bimi/<domain>/cert.pem (outside /v1) for verified domains only.
      #
      # @param id [String] Domain id
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [String] :from_name Display name used when an email's from has only an address. ""
      #   clears it. Limits: max 70 characters, no < > " or line breaks → 422 invalid_parameter
      # @option params [String] :logo_svg SVG source; normalized to SVG Tiny PS (fixes reported in logo_fixed,
