          model: Models::WebhookTestResult,
          request_options: request_options
        )
      end

      # List events.
      #
      # Events sent to this endpoint, newest first, each with its outcome and number of attempts (from the
      # endpoint’s last 100 delivery attempts). Requires a full-access key.
