    # zap.webhooks
    class Webhooks
      # @return [WebhooksEvents]
      attr_reader :events

      # @api private
      def initialize(client)
        @client = client
        @events = WebhooksEvents.new(client)
      end

      # List webhooks.
      #
      # List webhook endpoints (newest first); secrets are omitted. Requires a full-access key.
      # previous_secret_expires_at appears while a rotated secret still signs deliveries.
      #
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Page<ZapSMTP::Models::Webhook>]
      def list(request_options: {})
        @client.request_page(
          method: :get,
          path: "/webhooks",
          model: Models::Webhook,
          paging: nil,
          request_options: request_options
        )
      end

      # Create a webhook.
      #
      # Create a webhook endpoint; the signing secret is returned. Requires a full-access live key; test keys
      # get 403 test_key_restricted. The secret is also readable later via GET /webhooks/{id}. To send clicks
      # of one button to this endpoint: {"events": ["email.clicked"], "filter": {"actions":
      # ["confirm_order"]}}. Endpoints always return filter, with an empty list when there is none.
      #
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [String] :url Absolute https:// URL. Limits: 422 invalid_parameter "url must be an
      #   absolute https:// URL" Required.
