      #   Limits: otherwise 422 invalid_parameter "fg: colour must be RRGGBB or RRGGBBAA" Required.
      # @option params [String] :label_color Label colour, same format. Limits: 422 invalid_parameter "lc: …"
      #   Required.
      # @option params [String] :background Background colour, same format; alpha 00 (e.g. ffffff00) is
      #   transparent. Limits: 422 invalid_parameter "bg: …" Required.
