      #   up to 12 characters, without |. "" hides one label; four empty labels hide the label row. Limits: 422
      #   invalid_parameter "l must hold 4 labels separated by |" / "labels are limited to 12 characters"
      #   Default: ["days", "hours", "minutes", "seconds"].
