    end

    # zap.actions
    class Actions
      # @api private
      def initialize(client)
        @client = client
      end

      # List actions.
      #
      # List every action of the account: the ones you declared, the ones links named in the last 30 days, and
      # the ones templates and webhook filters use. Sorted by name. Requires a full-access key. declared is
      # false for an action that links use but nobody described; created_at and updated_at are then null.
      # clicks_7d, clicks_30d and unique_clickers_30d (distinct email and recipient pairs) count the last 7
      # and 30 days; last_click_at is null without a click in 30 days. templates counts the templates whose
      # draft or published HTML names the action; webhooks lists the ids of the endpoints filtered on it.
      #
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
      # @return [ZapSMTP::Page<ZapSMTP::Models::Action>]
      def list(request_options: {})
