          method: :get,
          path: "/actions",
          model: Models::Action,
          paging: nil,
          request_options: request_options
        )
      end

      # Declare an action.
      #
      # Declare an action and describe it. Optional: links work with any valid name, declared or not. Requires
      # a full-access live key; test keys get 403 test_key_restricted. The response does not count activity:
      # the stats are zero and templates is 0 here. Read them with GET /actions/{name}.
      #
      # @param params [Hash] the parameters below, also accepted as keyword arguments
      # @option params [String] :name The name links carry in data-zap-action: lowercase letters, digits, _, .
      #   and -, starting with a letter or digit, up to 64 characters. Limits: other names → 422
