          request_options: request_options
        )
      end

      # Delete a global variable.
      #
      # Delete a global variable. Sends with a template that still uses it then fail with 422
      # template_render_error until it is set again. Requires a full-access live key; test keys get 403
      # test_key_restricted.
      #
      # @param key [String] The key, used as {{global.key}}: letters, digits, _ and -, starting with a letter
      #   or _, up to 64; global is reserved. Limits: other keys → 422 invalid_parameter
      # @param request_options [Hash] :idempotency_key, :headers, :timeout and :max_retries for this call
